function repeatedSubtrees(root: TreeNode | null): TreeNode[] {
  const same = (a: TreeNode | null, b: TreeNode | null): boolean =>
    !a || !b ? a === b : a.val === b.val && same(a.left, b.left) && same(a.right, b.right);
  const nodes: TreeNode[] = [];
  const collect = (n: TreeNode | null) => { if (n) { nodes.push(n); collect(n.left); collect(n.right); } };
  collect(root);
  const out: TreeNode[] = [];
  for (let i = 0; i < nodes.length; i++) {
    if (out.some(o => same(o, nodes[i]))) continue;
    for (let j = i + 1; j < nodes.length; j++) {
      if (same(nodes[i], nodes[j])) { out.push(nodes[i]); break; }
    }
  }
  return out;
}

