        nodes = []

        def collect(n):
            if n:
                nodes.append(n)
                collect(n.left)
                collect(n.right)

        collect(root)
        out = []
        for i, a in enumerate(nodes):
            if any(same(o, a) for o in out):
                continue
            if any(same(a, nodes[j]) for j in range(i + 1, len(nodes))):
                out.append(a)
