  const seen = new Map<string, number>();
  const out: TreeNode[] = [];
  const ser = (n: TreeNode | null): string => {
    if (!n) return "#";
    const key = "(" + ser(n.left) + ")" + n.val + "(" + ser(n.right) + ")";
    const c = (seen.get(key) ?? 0) + 1;
    seen.set(key, c);
    if (c === 2) out.push(n);
    return key;
  };
  ser(root);
  return out;
}

